    public static void main(String[] args){mallow();mallowGates();blockedSwitch();mill();benchOrder();costs();ai();schema();System.out.println("NonPokemonBatch90Test passed: English/CN Mallow, payment-before-switch/mill, original-host healing/clamp, no-Bench/full-HP/hand gates, blocked switch, short and empty decks, opponent-first owner choices, immunity/no prizes/no permanent limit and both modes across four AI difficulties");}
    static void mallow(){for(String id:IDS.subList(0,2))for(UUID p:List.of(A,B))for(boolean extra:List.of(false,true))for(int damage:List.of(50,120,200)){
        var m=game(id,p,1,1);var source=hand(m,p,"trainer");UUID old=active(m,p),next=m.benchPokemonView(p).getFirst().pokemonId();NonPokemonBatch75Test.hurt(m,p,old,damage);NonPokemonBatch75Test.hurt(m,p,next,70);m.applySpecialConditionByEffect(p,p,SpecialCondition.POISONED);int size=m.privateView(p).hand().size();var rng=m.randomTranscript();play(m,p);check(active(m,p).equals(old)&&m.privateView(p).discard().isEmpty(),"Mallow switched or discarded before declaring extra payment");mode(m,p,extra?1:0);if(extra){var costs=pay(m,p,2);check(active(m,p).equals(old)&&m.privateView(p).discard().containsAll(costs),"Mallow did not pay before selecting/switching");var q=m.effectPokemonPrompt(p);m.chooseEffectPokemon(p,q.resolutionId(),q.step(),old);}var q=m.effectPokemonPrompt(p);m.chooseEffectPokemon(p,q.resolutionId(),q.step(),next);NonPokemonBatch67Test.settle(m);var outgoing=m.benchPokemonView(p).stream().filter(v->v.pokemonId().equals(old)).findFirst().orElseThrow();check(active(m,p).equals(next)&&m.activePokemonView(p).damage()==70&&outgoing.damage()==(extra?Math.max(0,damage-120):damage)&&outgoing.conditions().isEmpty(),"Mallow healed incoming/wrong host or wrong mode");check(m.privateView(p).hand().size()==size-1-(extra?2:0)&&m.privateView(p).discard().contains(source)&&!m.mayPlaySupporter(p)&&m.randomTranscript().equals(rng),"Mallow cost, completion or random mutation");
    }}
