        var m=game(IDS.getFirst(),p,bench?1:0,1);if(damage)NonPokemonBatch75Test.hurt(m,p,active(m,p),120);trim(m,p,cards);var source=hand(m,p,"trainer");var before=m.privateView(p);check(m.canPlayTrainer(p,source.instanceId(),null)==bench,"Mallow no-Bench gate");if(!bench){GeneratedRuleBatch8Test.reject(()->play(m,p));check(m.privateView(p).equals(before),"Rejected Mallow consumed card");continue;}play(m,p);check(m.canChooseEffectOption(p,1)==(damage&&cards>=3),"Additional Mallow gate ignored full HP or counted source card");if(!damage||cards<3){GeneratedRuleBatch8Test.reject(()->mode(m,p,1));check(m.privateView(p).hand().size()==cards-1,"Rejected extra payment changed hand");}mode(m,p,0);NonPokemonBatch67Test.settle(m);check(m.privateView(p).hand().size()==cards-1,"Base option paid an extra cost");
